package vn.edu.wspm.backend.persistence;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.stream.Stream;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import tools.jackson.databind.ObjectMapper;
import vn.edu.wspm.backend.services.run.persistence.PatternWeightPolicy;
import vn.edu.wspm.model.*;

/** Manual expected values; no fixture is generated by the policy under test. */
class PatternWeightPolicyTest {
    public record FixtureDocument(String fixtureVersion, String policyVersion, String classification,
                                  String researchIssue, String provenance, String sourceDiscrepancy, List<Fixture> cases) {}
    public record Fixture(String name, Map<String, String> weights, List<List<Integer>> itemsets, String expected, String reason) {}

    static FixtureDocument document() throws Exception {
        try (var input = PatternWeightPolicyTest.class.getResourceAsStream("/wdm/persistence/pattern-weight-policy-v1.json")) {
            assertNotNull(input); return new ObjectMapper().readValue(input, FixtureDocument.class);
        }
    }
    static Stream<Arguments> fixtures() throws Exception {
        return document().cases().stream().map(f -> Arguments.of(f.name(), f));
    }
    static Pattern pattern(List<List<Integer>> sets) {
        return new Pattern(sets.stream().map(set -> new Itemset(set.stream().map(Item::new).toList())).toList());
    }
    static void bits(double expected, double actual) {
        assertEquals(Double.doubleToRawLongBits(expected), Double.doubleToRawLongBits(actual));
    }

    @ParameterizedTest(name = "{0}") @MethodSource("fixtures")
    void manualExpectedValuesAndMapOrderPermutations(String name, Fixture fixture) {
        assertFalse(fixture.reason().isBlank());
        double expected = Double.parseDouble(fixture.expected());
        var entries = new ArrayList<>(fixture.weights().entrySet());
        for (int direction = 0; direction < 2; direction++) {
            var weights = new LinkedHashMap<Integer, Double>();
            entries.forEach(e -> weights.put(Integer.parseInt(e.getKey()), Double.parseDouble(e.getValue())));
            bits(expected, PatternWeightPolicy.calculate(pattern(fixture.itemsets()), weights));
            Collections.reverse(entries);
        }
        // Itemset canonical ordering, unlike temporal ordering, is numeric and independent of input order.
        var reversed = fixture.itemsets().stream().map(set -> {
            var copy = new ArrayList<>(set); Collections.reverse(copy); return (List<Integer>) copy;
        }).toList();
        var weights = new HashMap<Integer, Double>();
        fixture.weights().forEach((id, value) -> weights.put(Integer.parseInt(id), Double.parseDouble(value)));
        bits(expected, PatternWeightPolicy.calculate(pattern(reversed), weights));
    }

    @Test void fixtureVersionAndSourceClassificationDoNotClaimResearchResolution() throws Exception {
        var doc = document();
        assertEquals("PATTERN_WEIGHT_FIXTURES_V1", doc.fixtureVersion());
        assertEquals(PatternWeightPolicy.VERSION, doc.policyVersion());
        assertEquals("OWNER_SELECTED_APPLICATION_POLICY", doc.classification());
        assertEquals("R1_OPEN", doc.researchIssue());
        assertTrue(doc.provenance().contains("sections 5.2-5.4"));
        assertTrue(doc.sourceDiscrepancy().contains("0.229")); assertTrue(doc.sourceDiscrepancy().contains("0.559"));
    }

    static Stream<Double> invalidWeights() {
        return Stream.of(Double.NaN, Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY, 0.0, -0.0, -.1, Math.nextUp(1.0));
    }
    @ParameterizedTest @MethodSource("invalidWeights") void invalidPresentWeightsNeverBecomeDefaults(double weight) {
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(Pattern.singleton(new Item(1)), Map.of(1, weight)));
    }

    @Test void missingNullAndNoncommercialInputsReject() {
        var singleton = Pattern.singleton(new Item(1));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(null, Map.of(1, .5)));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(Pattern.empty(), Map.of(1, .5)));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(singleton, null));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(singleton, Map.of()));
        var nullWeight = new HashMap<Integer, Double>(); nullWeight.put(1, null);
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(singleton, nullWeight));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(Pattern.singleton(new Item(0)), Map.of(0, .5)));
        assertThrows(IllegalArgumentException.class, () -> PatternWeightPolicy.calculate(
                pattern(List.of(List.of(1, 2))), Map.of(1, .5)));
    }

    @Test void exactOneIsValidAndUnusedWeightsDoNotChangePatternProjection() {
        bits(1, PatternWeightPolicy.calculate(Pattern.singleton(new Item(1)), Map.of(1, 1.0, 2, .25)));
    }

    @Test void alteredAggregationAndTemporalSortingAreDetectedByManualFixtures() {
        var weights = Map.of(1, .125, 2, .375, 3, .5);
        var p = pattern(List.of(List.of(1, 2), List.of(3)));
        bits(.375, PatternWeightPolicy.calculate(p, weights));
        assertNotEquals(Double.doubleToRawLongBits(.375), Double.doubleToRawLongBits(1.0 / 3));
        assertNotEquals(Double.doubleToRawLongBits(.375), Double.doubleToRawLongBits(.5));
        var decimals = Map.of(1, .1, 2, .2, 3, .3);
        long forward = Double.doubleToRawLongBits(PatternWeightPolicy.calculate(pattern(List.of(List.of(1), List.of(2), List.of(3))), decimals));
        long reverse = Double.doubleToRawLongBits(PatternWeightPolicy.calculate(pattern(List.of(List.of(3), List.of(2), List.of(1))), decimals));
        assertNotEquals(forward, reverse);
    }
}
